    },
    {
      "topic": "Performance and runtime behavior on other platforms, target frameworks, or .NET SDKs (including AOT)",
      "reason": "Execution tests ran only on linux-x64 containers with SDKs 8.0.402 and 9.0.321; no cross-platform or performance evidence was provided.",
      "who_should_decide": "area owner",
      "blocking": false
    }
  ],
  "refutations": []
}
